/**
 * MarketplaceView — runspec runnable packages you can install into the
 * console's venvs and the connected fleet hosts' venvs.
 *
 * The catalogue is generated by the backend from package indexes (the console
 * venv's pip config + [[marketplace.repos]]): each entry is a distribution that
 * depends on `runspec`. Cards mirror the Forms tab (summary, tags, links) and
 * add the per-venv install state; Install / Uninstall open a target picker that
 * streams pip's output per target over `runspec:marketplace_progress`.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Alert, Badge, Button, Checkbox, Input, Modal, Progress, Segmented, Select, Space, Switch, Table, Tag, Tooltip, Typography, message } from 'antd'
import { AppstoreAddOutlined, UnorderedListOutlined, BookOutlined, CodeOutlined, DownloadOutlined, DeleteOutlined, HistoryOutlined, HomeOutlined, InfoCircleOutlined, ReloadOutlined, SearchOutlined, SettingOutlined } from '@ant-design/icons'
import { bridge, type Host, type MarketplaceCatalog, type MarketplaceEntry, type MarketplaceInstalled, type MarketplaceInstalledTarget, type MarketplaceOpPayload, type MarketplaceOpRecord, type MarketplaceOpTarget, type MarketplaceOpTargetState } from '../bridge'
import { useIsDark, useAccent, withAlpha, surfaces, RADIUS, textColor, textSecondary, textMuted, MONO_FONT } from '../ThemeContext'
import { antTone, RowActions, StatusTag, type StatusTone } from '../components/kit'
import { Markdown } from '../components/Markdown'
import { hasTargetTokens, hostPasses, parseSearch, type ParsedSearch } from '../searchTokens'
import { fmtWhen } from '../when'

export { parseSearch, type ParsedSearch }

const { Text, Link } = Typography

// ── pure helpers (exported for tests) ──────────────────────────────────────

/** A light PEP 440 comparison: numeric release parts, then a pre-release tag
 *  (a/b/rc/dev) sorts below the final. Enough to flag outdated installs. */
export function cmpVersion(a: string, b: string): number {
  const parse = (v: string) => {
    const m = /^v?(\d+(?:\.\d+)*)(?:[-._]?(a|b|c|rc|alpha|beta|pre|preview|dev)[-._]?(\d*))?/i.exec((v || '').trim())
    if (!m) return { rel: [-1], pre: 9, preN: 0 }
    const rel = m[1].split('.').map(n => parseInt(n, 10))
    while (rel.length > 1 && rel[rel.length - 1] === 0) rel.pop()
    const tag = (m[2] || '').toLowerCase()
    const pre = tag === '' ? 5 : tag === 'dev' ? 0 : tag.startsWith('a') ? 1 : tag.startsWith('b') ? 2 : 3
    return { rel, pre, preN: parseInt(m[3] || '0', 10) }
  }
  const x = parse(a), y = parse(b)
  const n = Math.max(x.rel.length, y.rel.length)
  for (let i = 0; i < n; i++) {
    const d = (x.rel[i] ?? 0) - (y.rel[i] ?? 0)
    if (d !== 0) return d < 0 ? -1 : 1
  }
  if (x.pre !== y.pre) return x.pre < y.pre ? -1 : 1
  if (x.preN !== y.preN) return x.preN < y.preN ? -1 : 1
  return 0
}

export type InstallState = 'absent' | 'current' | 'outdated' | 'newer' | 'unknown'

export interface TargetState {
  target: MarketplaceInstalledTarget
  installed: string | null
  state: InstallState
}

/** Per-target install state of one catalogue entry. */
export function targetStates(entry: MarketplaceEntry, installed: MarketplaceInstalled | null): TargetState[] {
  if (!installed) return []
  return installed.targets.map(t => {
    const v = t.ok ? t.dists[entry.name] ?? null : null
    let state: InstallState = 'absent'
    if (!t.ok) state = 'unknown'
    else if (v) {
      const c = entry.version ? cmpVersion(v, entry.version) : 0
      state = c === 0 ? 'current' : c < 0 ? 'outdated' : 'newer'
    }
    return { target: t, installed: v, state }
  })
}

export type ScopeFilter = 'all' | 'installed' | 'updates' | 'available'

/** Which venvs a `host:` / `group:` search keeps, or null when it names none.
 *  Each value is a case-insensitive substring (`host:web` = web-01, web-02);
 *  several of one kind are OR'd, host and group together are AND'd. */
export function targetFilter(
  p: ParsedSearch,
  groupOf: (host: string) => string | undefined,
): ((t: MarketplaceInstalledTarget) => boolean) | null {
  if (!hasTargetTokens(p)) return null
  return t => hostPasses(p, t.host, groupOf(t.host))
}

/** How many packages have an update on at least one of the given venvs. */
export function countUpdates(entries: MarketplaceEntry[], states: (e: MarketplaceEntry) => TargetState[]): number {
  return entries.filter(e => states(e).some(s => s.state === 'outdated')).length
}

export function searchMatch(e: MarketplaceEntry, q: string): boolean {
  const s = q.trim().toLowerCase()
  if (!s) return true
  const hay = [e.name, e.summary, e.repo_name, ...(e.keywords || []), ...(e.repos || [])].join(' ').toLowerCase()
  return s.split(/\s+/).every(w => hay.includes(w))
}

export function filterEntries(
  entries: MarketplaceEntry[],
  opts: { search: string; repo: string; scope: ScopeFilter },
  states: (e: MarketplaceEntry) => TargetState[],
): MarketplaceEntry[] {
  return entries.filter(e => {
    if (opts.repo && !(e.repos || []).includes(opts.repo)) return false
    if (!searchMatch(e, opts.search)) return false
    if (opts.scope === 'all') return true
    const st = states(e)
    const anyInstalled = st.some(s => s.installed)
    if (opts.scope === 'installed') return anyInstalled
    if (opts.scope === 'available') return !anyInstalled
    return st.some(s => s.state === 'outdated')
  })
}

function ago(ts: number | null | undefined): string {
  if (!ts) return 'never'
  const s = Math.max(0, Date.now() / 1000 - ts)
  if (s < 90) return 'just now'
  if (s < 3600) return `${Math.round(s / 60)} min ago`
  if (s < 86400) return `${Math.round(s / 3600)} h ago`
  return `${Math.round(s / 86400)} d ago`
}

const STATE_TONE: Record<InstallState, StatusTone> = {
  absent: 'neutral', current: 'ok', outdated: 'attention', newer: 'info', unknown: 'neutral',
}

// Above this many install chips the card would grow unbounded (a package on 70
// hosts), so the chip row gets a fixed-height scroll box + a count summary and
// the cards stay a uniform height in the grid.
const INSTALL_CHIPS_SCROLL_AT = 6
const INSTALL_CHIPS_MAX_H = 96  // ~4 rows of chips, then scroll

// ── cards ──────────────────────────────────────────────────────────────────

function PackageCard({ entry, states, filtered, running, onInstall, onUninstall, onDetails, onOpenOp }: {
  entry: MarketplaceEntry
  states: TargetState[]
  filtered?: boolean  // states are narrowed by a host:/group: search
  running?: MarketplaceOpRecord[]
  onOpenOp?: (op: string) => void
  onInstall: () => void
  onUninstall: () => void
  onDetails: () => void
}) {
  const isDark = useIsDark()
  const accent = useAccent()
  const [hovered, setHovered] = useState(false)
  const sf = surfaces(isDark)
  const border = hovered ? withAlpha(accent, 0.6) : sf.border
  const bg = hovered ? withAlpha(accent, isDark ? 0.05 : 0.03) : sf.raised

  const installedRows = states.filter(s => s.installed)
  const anyInstalled = installedRows.length > 0
  const anyOutdated = installedRows.some(s => s.state === 'outdated')
  const links = entry.links || {}

  return (
    <div
      className="rs-card-lift"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        border: `1px solid ${border}`, borderRadius: RADIUS.lg, padding: '14px 16px',
        background: bg, display: 'flex', flexDirection: 'column', gap: 6,
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }}>
        <Text style={{ fontFamily: MONO_FONT, fontSize: 14, fontWeight: 600 }}>{entry.name}</Text>
        <Tag style={{ fontSize: 11, margin: 0, fontFamily: MONO_FONT }}>{entry.version || '?'}</Tag>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 4 }}>
          {(running ?? []).map(o => (
            <Tooltip key={o.op} title="Running in the background. Click to see progress.">
              <StatusTag tone="running" onClick={() => onOpenOp?.(o.op)}>
                {o.action === 'uninstall' ? 'uninstalling…' : 'installing…'}
              </StatusTag>
            </Tooltip>
          ))}
          {anyOutdated && <StatusTag tone="attention">update available</StatusTag>}
          {anyInstalled && !anyOutdated && <StatusTag tone="ok">installed</StatusTag>}
          {entry.has_runspec_toml && (
            <StatusTag tone="info" tip="The wheel ships a runspec.toml — verified runnable package">verified</StatusTag>
          )}
        </div>
      </div>
      {entry.summary
        ? <Text type="secondary" style={{ fontSize: 13, lineHeight: 1.4 }}>{entry.summary}</Text>
        : <Text type="secondary" italic style={{ fontSize: 12 }}>No description published — add a summary to the package's pyproject.</Text>}
      <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', alignItems: 'center' }}>
        {(entry.repos || []).map(r => <Tag key={r} style={{ fontSize: 11, margin: 0 }}>{r === entry.repo ? entry.repo_name : r}</Tag>)}
        {(entry.keywords || []).slice(0, 6).map(k => <Tag key={k} style={{ fontSize: 11, margin: 0 }}>{k}</Tag>)}
      </div>
      {(links.documentation || links.homepage || links.source || links.changelog) && (
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', fontSize: 12 }}>
          {links.documentation && <Link href={links.documentation} target="_blank" rel="noreferrer"><BookOutlined /> Docs</Link>}
          {links.homepage && <Link href={links.homepage} target="_blank" rel="noreferrer"><HomeOutlined /> Home</Link>}
          {links.source && <Link href={links.source} target="_blank" rel="noreferrer"><CodeOutlined /> Source</Link>}
          {links.changelog && <Link href={links.changelog} target="_blank" rel="noreferrer"><HistoryOutlined /> Changelog</Link>}
        </div>
      )}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4, marginTop: 2 }}>
        {installedRows.length === 0 ? (
          <Text style={{ fontSize: 11, color: textMuted(isDark) }}>{filtered ? 'Not installed on the filtered hosts' : 'Not installed on any venv'}</Text>
        ) : (
          <>
            {installedRows.length > INSTALL_CHIPS_SCROLL_AT && (
              <Text style={{ fontSize: 11, color: textMuted(isDark) }}>
                Installed on {installedRows.length} venvs
                {anyOutdated ? ` · ${installedRows.filter(s => s.state === 'outdated').length} to update` : ''}
              </Text>
            )}
            <div
              style={{
                display: 'flex', gap: 4, flexWrap: 'wrap', alignItems: 'flex-start',
                // Past the threshold, box + scroll so a package on many hosts
                // doesn't stretch the card out of line with its neighbours.
                maxHeight: installedRows.length > INSTALL_CHIPS_SCROLL_AT ? INSTALL_CHIPS_MAX_H : undefined,
                overflowY: installedRows.length > INSTALL_CHIPS_SCROLL_AT ? 'auto' : undefined,
              }}
            >
              {/* Outdated chips first, so what needs updating is visible without scrolling. */}
              {[...installedRows].sort((a, b) => (a.state === 'outdated' ? 0 : 1) - (b.state === 'outdated' ? 0 : 1)).map(s => (
                <StatusTag key={s.target.id} tone={STATE_TONE[s.state]} mono
                  tip={`${s.target.path} — ${s.state === 'outdated' ? `${s.installed} → ${entry.version} available` : s.state}`}>
                  {s.target.host}/{s.target.venv} {s.installed}{s.state === 'outdated' ? ' ↑' : ''}
                </StatusTag>
              ))}
            </div>
          </>
        )}
      </div>
      {/* Install / Update is the card's action; Uninstall waits behind More so
          it never sits beside Update looking just as safe. */}
      <RowActions
        style={{ marginTop: 4 }}
        primary={{ key: 'install', label: anyOutdated ? 'Update…' : anyInstalled ? 'Install / reinstall…' : 'Install…', icon: <DownloadOutlined />, onClick: onInstall }}
        secondary={[{ key: 'details', label: 'Details', icon: <InfoCircleOutlined />, onClick: onDetails }]}
        more={anyInstalled ? [{ key: 'uninstall', label: 'Uninstall…', icon: <DeleteOutlined />, danger: true, onClick: onUninstall }] : []}
      />
    </div>
  )
}

// ── details modal ──────────────────────────────────────────────────────────

function DetailsModal({ entry, onClose }: { entry: MarketplaceEntry | null; onClose: () => void }) {
  const isDark = useIsDark()
  if (!entry) return null
  const rows: [string, string][] = [
    ['Latest version', entry.version],
    ['Repo', `${entry.repo_name} — ${entry.repo_url}`],
    ['Requires Python', entry.requires_python || '—'],
    ['Depends on', (entry.requires_dist || []).join(', ') || '—'],
    ['License', entry.license || '—'],
    ['Author', entry.author || '—'],
    ['Released', entry.upload_time ? fmtWhen(entry.upload_time) : '—'],
    ['Metadata read from', entry.metadata_source || '—'],
  ]
  return (
    <Modal open title={<span style={{ fontFamily: MONO_FONT }}>{entry.name} {entry.version}</span>} width={760} onCancel={onClose} footer={null}>
      {entry.summary && <Text style={{ fontSize: 13 }}>{entry.summary}</Text>}
      <div style={{ display: 'grid', gridTemplateColumns: 'max-content 1fr', gap: '4px 14px', fontSize: 12, margin: '12px 0' }}>
        {rows.map(([k, v]) => (
          <span key={k} style={{ display: 'contents' }}>
            <span style={{ color: textSecondary(isDark) }}>{k}</span>
            <span style={{ fontFamily: MONO_FONT, wordBreak: 'break-word' }}>{v}</span>
          </span>
        ))}
      </div>
      {entry.versions?.length > 1 && (
        <div style={{ marginBottom: 12, display: 'flex', gap: 4, flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={{ fontSize: 12, color: textSecondary(isDark) }}>Versions:</span>
          {entry.versions.map(v => <Tag key={v} style={{ fontSize: 11, margin: 0, fontFamily: MONO_FONT }}>{v}</Tag>)}
        </div>
      )}
      {entry.description ? (
        <div style={{ maxHeight: '50vh', overflow: 'auto', border: '1px solid var(--rs-border)', borderRadius: RADIUS.md, padding: '8px 12px' }}>
          {(entry.description_content_type || '').includes('markdown') || !entry.description_content_type
            ? <Markdown color={textColor(isDark)}>{entry.description}</Markdown>
            : <pre style={{ whiteSpace: 'pre-wrap', fontFamily: MONO_FONT, fontSize: 12, margin: 0 }}>{entry.description}</pre>}
          {entry.description_truncated && <Text type="secondary" style={{ fontSize: 11 }}>(description truncated)</Text>}
        </div>
      ) : (
        <Text type="secondary" style={{ fontSize: 12 }}>The package publishes no long description.</Text>
      )}
    </Modal>
  )
}

// ── install / uninstall picker ─────────────────────────────────────────────

interface RowChoice { checked: boolean; run_as: string; become_method: 'sudo' | 'su' }

export function defaultRunAs(t: MarketplaceInstalledTarget): string {
  return !t.local && t.ok && t.owner && t.user && t.owner !== t.user ? t.owner : ''
}

/** One host in the picker and the venvs on it, in the order they were probed. */
export interface HostGroup { host: string; group: string; rows: TargetState[] }

export function groupByHost(rows: TargetState[], groupOf?: (host: string) => string | undefined): HostGroup[] {
  const out: HostGroup[] = []
  const at = new Map<string, HostGroup>()
  for (const s of rows) {
    let g = at.get(s.target.host)
    if (!g) {
      g = { host: s.target.host, group: groupOf?.(s.target.host) || '', rows: [] }
      at.set(s.target.host, g)
      out.push(g)
    }
    g.rows.push(s)
  }
  return out
}

/** The picker's filter: every word must appear in the host, its group, the
 *  venv name or its path. A host that matches keeps all its venvs; otherwise
 *  only the venvs that match stay. `group` (a group chip) must match exactly. */
export function filterHostGroups(groups: HostGroup[], text: string, group: string): HostGroup[] {
  const words = text.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const has = (hay: string) => words.every(w => hay.toLowerCase().includes(w))
  const out: HostGroup[] = []
  for (const g of groups) {
    if (group && g.group !== group) continue
    if (!words.length || has(`${g.host} ${g.group}`)) { out.push(g); continue }
    const rows = g.rows.filter(s => has(`${g.host} ${g.group} ${s.target.venv} ${s.target.path}`))
    if (rows.length) out.push({ ...g, rows })
  }
  return out
}

/** Which venvs a quick-tick button picks. */
export type TickPick = 'outdated' | 'absent' | 'all' | 'none'

export function tickMatches(s: TargetState, pick: TickPick): boolean {
  if (pick === 'all') return true
  if (pick === 'none') return false
  if (pick === 'outdated') return s.state === 'outdated'
  return !s.installed
}

/** Short summary of a host's venvs for its collapsed row. */
export function hostSummary(rows: TargetState[]): { outdated: number; current: number; absent: number; other: number } {
  const c = { outdated: 0, current: 0, absent: 0, other: 0 }
  for (const s of rows) {
    if (s.state === 'outdated') c.outdated++
    else if (s.state === 'current') c.current++
    else if (!s.installed) c.absent++
    else c.other++
  }
  return c
}

// Below this many venvs every host starts expanded (the picker looks like a
// plain list); above it hosts start collapsed to one row each.
const EXPAND_ALL_UP_TO = 12

type PickerRow =
  | { key: string; kind: 'host'; g: HostGroup; children: PickerRow[] }
  | { key: string; kind: 'venv'; s: TargetState; solo: boolean }

/** Pick the venvs + options, start the op, hand its id back. The op then runs
 *  in the background: the picker closes and the activity view follows it, so
 *  the operator can start the next one without waiting.
 *
 *  Venvs are grouped by host: a host with one venv is a single row, a host with
 *  several is one row with a part-tick box that expands to its venvs. Only the
 *  list scrolls, so the buttons stay on screen however big the fleet is. */
function OpModal({ entry, action, states, focus, groupOf, onClose, onStarted }: {
  entry: MarketplaceEntry
  action: 'install' | 'uninstall'
  states: TargetState[]
  // A host:/group: search in force: only its venvs start ticked (the rest are
  // still listed, so widening the pick is one click).
  focus?: ((t: MarketplaceInstalledTarget) => boolean) | null
  groupOf?: (host: string) => string | undefined
  onClose: () => void
  onStarted: (op: string) => void
}) {
  const isDark = useIsDark()
  const accent = useAccent()
  const rowsAll = useMemo(() => states.filter(s => s.target.connected && s.target.ok), [states])
  const eligible = useMemo(
    () => (action === 'uninstall' ? rowsAll.filter(s => s.installed) : rowsAll),
    [rowsAll, action],
  )
  const [choice, setChoice] = useState<Record<string, RowChoice>>(() => {
    const init: Record<string, RowChoice> = {}
    for (const s of eligible) {
      const inFocus = !focus || focus(s.target)
      const pool = focus ? states.filter(x => focus(x.target)) : states
      // Uninstall starts with nothing ticked: on a fleet a pre-ticked list is one
      // click from removing a package from every venv. Install/update keeps its
      // helpful defaults (outdated venvs, or every venv when none has it).
      const preselect = inFocus && action !== 'uninstall' && (s.state === 'outdated' || (s.state === 'absent' && !pool.some(x => x.installed)))
      init[s.target.id] = { checked: preselect, run_as: defaultRunAs(s.target), become_method: 'sudo' }
    }
    return init
  })
  const [version, setVersion] = useState<string>('')  // '' = latest
  const [reinstall, setReinstall] = useState(false)
  const [upgradeRunspec, setUpgradeRunspec] = useState(false)
  const [starting, setStarting] = useState(false)
  const [filter, setFilter] = useState('')
  const [groupPick, setGroupPick] = useState('')

  const hostGroups = useMemo(() => groupByHost(eligible, groupOf), [eligible, groupOf])
  const [expanded, setExpanded] = useState<string[]>(
    () => (eligible.length <= EXPAND_ALL_UP_TO ? hostGroups.filter(g => g.rows.length > 1).map(g => `h:${g.host}`) : []),
  )
  const groupNames = useMemo(() => [...new Set(hostGroups.map(g => g.group).filter(Boolean))].sort(), [hostGroups])
  const shownGroups = useMemo(() => filterHostGroups(hostGroups, filter, groupPick), [hostGroups, filter, groupPick])
  const shown = useMemo(() => shownGroups.flatMap(g => g.rows), [shownGroups])
  const narrowed = !!filter.trim() || !!groupPick

  const selected = eligible.filter(s => choice[s.target.id]?.checked)
  const selectedHosts = new Set(selected.map(s => s.target.host)).size
  const shownIds = new Set(shown.map(s => s.target.id))
  const hiddenTicked = selected.filter(s => !shownIds.has(s.target.id)).length
  const spec = version ? `${entry.name}==${version}` : entry.name
  const upgrade = action === 'install' && !version && selected.some(s => s.installed)
  const isRunspec = entry.name.toLowerCase() === 'runspec'

  const setChecked = (ids: string[], checked: boolean) => setChoice(c => {
    const next = { ...c }
    for (const id of ids) next[id] = { ...next[id], checked }
    return next
  })
  const setField = (id: string, patch: Partial<RowChoice>) => setChoice(c => ({ ...c, [id]: { ...c[id], ...patch } }))
  // A quick-tick button sets the venvs on screen (ticking the matches and
  // unticking the rest); venvs a filter hides keep their ticks.
  const tick = (pick: TickPick) => setChoice(c => {
    const next = { ...c }
    for (const s of shown) next[s.target.id] = { ...next[s.target.id], checked: tickMatches(s, pick) }
    return next
  })

  const start = async () => {
    if (selected.length === 0) { message.warning('Pick at least one venv.'); return }
    setStarting(true)
    try {
      const targets: MarketplaceOpTarget[] = selected.map(s => ({
        id: s.target.id,
        ...(choice[s.target.id].run_as ? { run_as: choice[s.target.id].run_as, become_method: choice[s.target.id].become_method } : {}),
      }))
      const payload: MarketplaceOpPayload = {
        package: spec, targets, upgrade, reinstall, repo: entry.repo,
        upgrade_runspec: action === 'install' && !isRunspec && upgradeRunspec,
        ...(action === 'install' && !version && entry.version ? { expect_version: entry.version } : {}),
      }
      const res = action === 'install' ? await bridge.marketplace_install(payload) : await bridge.marketplace_uninstall(payload)
      onStarted(res.op)
    } catch (e) {
      message.error(e instanceof Error ? e.message : `Could not start ${action}`)
    } finally {
      setStarting(false)
    }
  }

  const title = action === 'install'
    ? `${states.some(s => s.installed) ? 'Install / update' : 'Install'} ${entry.name}`
    : `Uninstall ${entry.name}`

  const data: PickerRow[] = shownGroups.map(g => (g.rows.length === 1
    ? { key: g.rows[0].target.id, kind: 'venv' as const, s: g.rows[0], solo: true }
    : { key: `h:${g.host}`, kind: 'host' as const, g, children: g.rows.map(s => ({ key: s.target.id, kind: 'venv' as const, s, solo: false })) }))
  // While a filter is on, every host it keeps is open, so the matching venvs show.
  const expandedKeys = narrowed ? data.filter(r => r.kind === 'host').map(r => r.key) : expanded

  const mono = { fontFamily: MONO_FONT }
  const meta = { color: textMuted(isDark), fontSize: 12 }
  const installedTag = (s: TargetState) => s.installed
    ? <StatusTag tone={STATE_TONE[s.state]} mono>{s.installed}{s.state === 'outdated' ? ` → ${entry.version}` : ''}</StatusTag>
    : <Text type="secondary" style={{ fontSize: 12 }}>—</Text>
  const hostLabel = (g: { host: string; group: string }) => (
    <>
      <span style={mono}>{g.host}</span>
      {g.group && <span style={{ ...meta, marginLeft: 6 }}>{g.group}</span>}
    </>
  )

  const columns = [
    {
      title: '', key: 'tick', width: 40,
      render: (_: unknown, r: PickerRow) => {
        if (r.kind === 'venv') {
          return <Checkbox checked={!!choice[r.s.target.id]?.checked} aria-label={`${r.s.target.host} ${r.s.target.venv}`}
            onChange={e => setChecked([r.s.target.id], e.target.checked)} />
        }
        const ids = r.g.rows.map(s => s.target.id)
        const n = ids.filter(id => choice[id]?.checked).length
        return <Checkbox checked={n === ids.length} indeterminate={n > 0 && n < ids.length} aria-label={`all venvs on ${r.g.host}`}
          onChange={e => setChecked(ids, e.target.checked)} />
      },
    },
    {
      title: 'Host / venv', key: 'where',
      render: (_: unknown, r: PickerRow) => {
        if (r.kind === 'host') {
          return <>{hostLabel(r.g)}<span style={{ ...meta, marginLeft: 6 }}>· {r.g.rows.length} venvs</span></>
        }
        const venv = <Tooltip title={r.s.target.path}><span style={mono}>{r.s.target.venv}</span></Tooltip>
        if (!r.solo) return venv
        return <>{hostLabel({ host: r.s.target.host, group: groupOf?.(r.s.target.host) || '' })}<span style={{ ...meta, margin: '0 6px' }}>/</span>{venv}</>
      },
    },
    {
      title: 'Python', key: 'py', width: 90,
      render: (_: unknown, r: PickerRow) => r.kind === 'venv'
        ? <span style={{ ...mono, fontSize: 12 }}>{r.s.target.python_version || '?'}</span>
        : null,
    },
    {
      title: 'Installed', key: 'installed',
      render: (_: unknown, r: PickerRow) => {
        if (r.kind === 'venv') return installedTag(r.s)
        const c = hostSummary(r.g.rows)
        return (
          <Space size={4} wrap>
            {c.outdated > 0 && <StatusTag tone={STATE_TONE.outdated}>{c.outdated} outdated</StatusTag>}
            {c.current > 0 && <StatusTag tone={STATE_TONE.current}>{c.current} current</StatusTag>}
            {c.other > 0 && <StatusTag tone="neutral">{c.other} other</StatusTag>}
            {c.absent > 0 && <span style={meta}>{c.absent} not installed</span>}
          </Space>
        )
      },
    },
    {
      title: <Tooltip title="Escalate with sudo -n -u / su when the venv belongs to a service account (pre-filled from the venv's owner). Leave blank to run as the SSH login user."><span>Run as</span></Tooltip>,
      key: 'runas', width: 210,
      render: (_: unknown, r: PickerRow) => {
        if (r.kind === 'host') {
          const who = [...new Set(r.g.rows.map(s => (s.target.local ? 'this machine' : choice[s.target.id]?.run_as || 'login user')))]
          return (
            <Tooltip title={<>{who.join(', ')}<br />Expand the host to change it.</>}>
              <span style={{ ...meta, ...mono, whiteSpace: 'nowrap' }}>{who[0]}{who.length > 1 ? ` +${who.length - 1}` : ''}</span>
            </Tooltip>
          )
        }
        const s = r.s
        return s.target.local
          ? <Text type="secondary" style={{ fontSize: 12 }}>this machine</Text>
          : (
            <Space.Compact size="small">
              <Input value={choice[s.target.id]?.run_as ?? ''} placeholder={s.target.user || 'login user'}
                aria-label={`Run as on ${s.target.host} ${s.target.venv}`}
                style={{ ...mono, width: 120 }}
                onChange={e => setField(s.target.id, { run_as: e.target.value })} />
              <Select size="small" aria-label={`How to switch user on ${s.target.host}`} value={choice[s.target.id]?.become_method ?? 'sudo'} disabled={!choice[s.target.id]?.run_as}
                options={[{ value: 'sudo', label: 'sudo' }, { value: 'su', label: 'su' }]} style={{ width: 72 }}
                onChange={v => setField(s.target.id, { become_method: v })} />
            </Space.Compact>
          )
      },
    },
  ]

  const count = (pick: TickPick) => shown.filter(s => tickMatches(s, pick)).length
  const picks: { pick: TickPick; label: string }[] = action === 'install'
    ? [{ pick: 'outdated', label: 'Outdated' }, { pick: 'absent', label: 'Not installed' }, { pick: 'all', label: 'All' }]
    : [{ pick: 'all', label: 'All' }, { pick: 'outdated', label: 'Outdated' }]

  return (
    <Modal
      open
      title={title}
      width={900}
      style={{ top: 40 }}
      onCancel={onClose}
      footer={
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          {eligible.length > 0 && (
            <span style={{ ...meta, marginRight: 'auto', textAlign: 'left' }}>
              {selected.length} of {eligible.length} venv{eligible.length === 1 ? '' : 's'} ticked
              {selected.length > 0 && hostGroups.length > 1 ? ` on ${selectedHosts} host${selectedHosts === 1 ? '' : 's'}` : ''}
              {hiddenTicked > 0 ? ` · ${hiddenTicked} not shown by the filter` : ''}
            </span>
          )}
          <Button onClick={onClose} style={{ marginLeft: 'auto' }}>Cancel</Button>
          <Button type="primary" danger={action === 'uninstall'} loading={starting} onClick={start} disabled={eligible.length === 0}
            icon={action === 'install' ? <DownloadOutlined /> : <DeleteOutlined />}>
            {action === 'install' ? `Install ${spec}` : `Uninstall ${entry.name}`} on {selected.length} venv{selected.length === 1 ? '' : 's'}
          </Button>
        </div>
      }
    >
      {eligible.length === 0 ? (
        <Alert type="info" showIcon message={action === 'uninstall' ? 'Not installed on any connected venv.' : 'No connected venv to install into — connect a host or add a local venv (Settings → Local venvs).'} />
      ) : (
        <>
          {action === 'install' && (
            <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginBottom: 10, flexWrap: 'wrap', fontSize: 13 }}>
              <span>
                <span style={{ color: textSecondary(isDark), marginRight: 6 }}>Version</span>
                <Select size="small" aria-label="Version" value={version} style={{ width: 160 }}
                  options={[{ value: '', label: `latest (${entry.version})` }, ...(entry.versions || []).filter(v => v !== entry.version).map(v => ({ value: v, label: v }))]}
                  onChange={v => setVersion(v)} />
              </span>
              <span>
                <Switch size="small" checked={reinstall} onChange={setReinstall} aria-label="Force reinstall" />
                <span style={{ marginLeft: 6 }}>Force reinstall</span>
              </span>
              {!isRunspec && (
                <Tooltip title="Also upgrade the runspec library in each selected venv, in the same pip run (pip install -U <package> runspec).">
                  <span>
                    <Switch size="small" checked={upgradeRunspec} onChange={setUpgradeRunspec} aria-label="Also upgrade runspec" />
                    <span style={{ marginLeft: 6 }}>Also upgrade runspec</span>
                  </span>
                </Tooltip>
              )}
              {upgrade && <Text type="secondary" style={{ fontSize: 12 }}>Already-installed venvs will be upgraded (pip install -U).</Text>}
              {entry.repo && <Text type="secondary" style={{ fontSize: 12 }}>From {entry.repo_name}.</Text>}
            </div>
          )}
          <div style={{ display: 'flex', gap: 6, alignItems: 'center', marginBottom: 8, flexWrap: 'wrap' }}>
            <span style={meta}>Tick:</span>
            {picks.map(p => {
              const n = count(p.pick)
              return n > 0 || p.pick === 'all'
                ? <Button key={p.pick} size="small" onClick={() => tick(p.pick)}>{p.label} {n}</Button>
                : null
            })}
            <Button size="small" onClick={() => tick('none')}>None</Button>
            {groupNames.length > 1 && (
              <>
                <span style={{ ...meta, marginLeft: 8 }}>Group:</span>
                {groupNames.map(gn => (
                  <Tag.CheckableTag key={gn} checked={groupPick === gn} onChange={on => setGroupPick(on ? gn : '')}
                    style={groupPick === gn ? undefined : { border: `1px solid ${withAlpha(accent, 0.35)}` }}>
                    {gn}
                  </Tag.CheckableTag>
                ))}
              </>
            )}
            {hostGroups.length > 1 && (
              <Input size="small" allowClear prefix={<SearchOutlined />} placeholder="Filter host, group or venv"
                value={filter} onChange={e => setFilter(e.target.value)} style={{ width: 220, marginLeft: 'auto' }} />
            )}
          </div>
          <Table<PickerRow>
            size="small"
            rowKey="key"
            dataSource={data}
            columns={columns}
            pagination={false}
            scroll={{ y: 'max(200px, calc(100vh - 400px))' }}
            locale={{ emptyText: 'No venv matches the filter.' }}
            expandable={{
              expandedRowKeys: expandedKeys,
              onExpandedRowsChange: keys => { if (!narrowed) setExpanded(keys as string[]) },
              expandIconColumnIndex: 1,
              indentSize: 20,
            }}
          />
        </>
      )}
    </Modal>
  )
}

// ── activity: running + recent ops ─────────────────────────────────────────

/** "Installing runspec-jira" while running, then "Install runspec-jira". */
export function opLabel(op: Pick<MarketplaceOpRecord, 'action' | 'package' | 'status'>): string {
  const verb = op.action === 'uninstall' ? 'Uninstall' : 'Install'
  return `${op.status === 'running' ? `${verb}ing` : verb} ${op.package}`
}

/** Status tag colour + text for one op, from its per-target counts. */
export function opOutcome(op: MarketplaceOpRecord): { color: string; text: string } {
  const c = op.counts ?? { ok: 0, failed: 0, running: 0, queued: 0, skipped: 0 }
  const total = (op.targets?.length ?? 0) || c.ok + c.failed + c.running + c.queued + c.skipped
  if (op.status === 'running') {
    const done = c.ok + c.failed + c.skipped
    return { color: 'processing', text: `${done}/${total} done${c.queued ? ` · ${c.queued} queued` : ''}` }
  }
  if (op.status === 'cancelled') return { color: 'default', text: 'cancelled' }
  if (c.failed) return { color: 'red', text: `${c.failed} of ${total} failed` }
  return { color: 'green', text: total === 1 ? 'ok' : `ok on ${total}` }
}

/** Apply one runspec:marketplace_progress event to an op record (pure). */
export function applyProgress(rec: MarketplaceOpRecord, d: Record<string, unknown>): MarketplaceOpRecord {
  const targets = (rec.targets ?? []).map(t => {
    if (t.target !== d.target) return t
    if (d.phase === 'start') return { ...t, state: 'running' as const }
    if (d.phase === 'line') return { ...t, lines: [...(t.lines ?? []), String(d.line)].slice(-400) }
    if (d.phase === 'done') return { ...t, state: 'done' as const, ok: !!d.ok, exit_code: (d.exit_code as number | null) ?? null, summary: String(d.summary ?? ''), ...(d.not_updated ? { not_updated: true } : {}) }
    return t
  })
  return { ...rec, targets }
}

const TARGET_STATE_TAG: Record<string, { color: string; text: string }> = {
  queued: { color: 'default', text: 'queued' },
  running: { color: 'processing', text: 'running…' },
  skipped: { color: 'default', text: 'skipped' },
}

/** One venv's place in an op, for the status filter and counts. */
export type TargetStatus = 'failed' | 'running' | 'queued' | 'ok' | 'skipped'

export function targetStatus(t: MarketplaceOpTargetState): TargetStatus {
  if (t.state === 'done') return t.ok ? 'ok' : 'failed'
  return t.state
}

export function statusCounts(targets: MarketplaceOpTargetState[]): Record<TargetStatus, number> {
  const c: Record<TargetStatus, number> = { failed: 0, running: 0, queued: 0, ok: 0, skipped: 0 }
  for (const t of targets) c[targetStatus(t)]++
  return c
}

/** The line a collapsed row shows: the newest output line, else the summary. */
export function lastLine(t: MarketplaceOpTargetState): string {
  const lines = t.lines ?? []
  for (let i = lines.length - 1; i >= 0; i--) if (lines[i].trim()) return lines[i].trim()
  return t.summary ?? ''
}

// Up to this many venvs every row opens with its pip output showing; past it
// rows are one line each (status + newest output line) and open on click.
const OP_EXPAND_ALL_UP_TO = 3

/** One op's per-venv status + pip output, live while it runs. Closing never
 *  stops it — re-open it from the activity list.
 *
 *  Each venv is one row (status + newest output line); click a row for its
 *  full output. Only the list scrolls, so Close / Cancel stay in view however
 *  many venvs the op covers. */
function OpDetailModal({ opId, onClose }: { opId: string; onClose: () => void }) {
  const isDark = useIsDark()
  const [rec, setRec] = useState<MarketplaceOpRecord | null>(null)
  const [missing, setMissing] = useState(false)
  const [show, setShow] = useState<'all' | TargetStatus>('all')
  const [filter, setFilter] = useState('')
  const [expanded, setExpanded] = useState<string[] | null>(null)  // null = default (set once loaded)

  useEffect(() => {
    let alive = true
    const load = async () => {
      try {
        const r = await bridge.marketplace_op(opId)
        if (!alive) return
        if (r) setRec(r)
        else setMissing(true)
      } catch { /* keep what we have */ }
    }
    load()
    const onProgress = (e: Event) => {
      const d = (e as CustomEvent).detail || {}
      if (d.op !== opId) return
      setRec(prev => (prev ? applyProgress(prev, d) : prev))
    }
    const onDone = (e: Event) => {
      const d = (e as CustomEvent).detail || {}
      if (d.op === opId) load()
    }
    window.addEventListener('runspec:marketplace_progress', onProgress)
    window.addEventListener('runspec:marketplace_done', onDone)
    return () => {
      alive = false
      window.removeEventListener('runspec:marketplace_progress', onProgress)
      window.removeEventListener('runspec:marketplace_done', onDone)
    }
  }, [opId])

  const cancel = async () => { await bridge.marketplace_cancel(opId).catch(() => {}) }
  const opts = rec?.options ?? {}
  const flags = [opts.upgrade && 'upgrade', opts.reinstall && 'force reinstall', opts.upgrade_runspec && 'also upgrade runspec', opts.pre && 'pre-releases'].filter(Boolean) as string[]
  const targets = rec?.targets ?? []
  const few = targets.length <= OP_EXPAND_ALL_UP_TO
  const counts = statusCounts(targets)
  const words = filter.trim().toLowerCase().split(/\s+/).filter(Boolean)
  const shown = targets.filter(t =>
    (show === 'all' || targetStatus(t) === show)
    && words.every(w => `${t.host} ${t.venv}`.toLowerCase().includes(w)))
  const openKeys = expanded ?? (few ? targets.map(t => t.target) : [])
  const done = counts.ok + counts.failed + counts.skipped
  // The live per-venv states are newer than the record's counts while it runs.
  const outcome = rec ? opOutcome(targets.length ? { ...rec, counts } : rec) : null

  const statusTag = (t: MarketplaceOpTargetState) => {
    const tag = t.state === 'done'
      ? t.not_updated
        ? { color: 'orange', text: 'not updated' }
        : { color: t.ok ? 'green' : 'red', text: t.ok ? 'ok' : `failed (exit ${t.exit_code ?? '?'})` }
      : TARGET_STATE_TAG[t.state]
    return <StatusTag tone={antTone(tag.color)}>{tag.text}</StatusTag>
  }
  const columns = [
    {
      title: 'Host / venv', key: 'where', width: 260,
      render: (_: unknown, t: MarketplaceOpTargetState) => <Text style={{ fontFamily: MONO_FONT, fontSize: 12, fontWeight: 600 }}>{t.host}/{t.venv}</Text>,
    },
    { title: 'Status', key: 'status', width: 150, render: (_: unknown, t: MarketplaceOpTargetState) => statusTag(t) },
    {
      title: 'Output', key: 'last', ellipsis: true,
      render: (_: unknown, t: MarketplaceOpTargetState) => {
        if (openKeys.includes(t.target)) return null  // the full output shows below the row
        const line = t.state === 'queued' ? 'Waiting for another operation on this venv to finish.' : lastLine(t)
        return <span style={{ fontFamily: t.state === 'queued' ? undefined : MONO_FONT, fontSize: 11, color: textMuted(isDark) }}>{line}</span>
      },
    },
  ]
  const segment = (key: TargetStatus, label: string) => (counts[key] ? [{ value: key, label: `${label} ${counts[key]}` }] : [])

  return (
    <Modal
      open
      title={rec ? opLabel(rec) : 'Marketplace operation'}
      width={900}
      style={{ top: 40 }}
      onCancel={onClose}
      footer={
        <Space>
          {rec?.status === 'running' && <Button onClick={cancel}>Cancel operation</Button>}
          <Button type="primary" onClick={onClose}>Close</Button>
        </Space>
      }
    >
      {missing ? (
        <Alert type="info" showIcon message="This operation is no longer in the activity history." />
      ) : !rec ? (
        <Text type="secondary">Loading…</Text>
      ) : (
        <>
          <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', marginBottom: 8, fontSize: 12, color: textSecondary(isDark) }}>
            <StatusTag tone={antTone(outcome!.color)}>{outcome!.text}</StatusTag>
            <span>started {ago(rec.started_at)}</span>
            {rec.status === 'running' && <span>Closing this keeps it running; reopen it from Activity.</span>}
            {flags.length > 0 && <span>· {flags.join(', ')}</span>}
          </div>
          {targets.length > 1 && (
            <Progress size="small" showInfo={false} style={{ margin: '0 0 8px' }}
              percent={Math.round((100 * done) / targets.length)}
              success={{ percent: Math.round((100 * (counts.ok + counts.skipped)) / targets.length) }}
              status={counts.failed ? 'exception' : rec.status === 'running' ? 'active' : 'normal'} />
          )}
          {!few && (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 8, flexWrap: 'wrap' }}>
              <Segmented size="small" value={show} onChange={v => setShow(v as 'all' | TargetStatus)}
                options={[
                  { value: 'all', label: `All ${targets.length}` },
                  ...segment('failed', 'Failed'), ...segment('running', 'Running'), ...segment('queued', 'Queued'),
                  ...segment('ok', 'OK'), ...segment('skipped', 'Skipped'),
                ]} />
              <Input size="small" allowClear prefix={<SearchOutlined />} placeholder="Filter host or venv"
                value={filter} onChange={e => setFilter(e.target.value)} style={{ width: 200, marginLeft: 'auto' }} />
              <Button size="small" onClick={() => setExpanded(shown.map(t => t.target))}>Expand shown</Button>
              <Button size="small" onClick={() => setExpanded([])}>Collapse all</Button>
            </div>
          )}
          <Table<MarketplaceOpTargetState>
            size="small"
            rowKey="target"
            dataSource={shown}
            columns={columns}
            pagination={false}
            showHeader={!few}
            scroll={{ y: 'max(200px, calc(100vh - 380px))' }}
            locale={{ emptyText: 'No venv matches.' }}
            expandable={{
              expandedRowKeys: openKeys,
              onExpandedRowsChange: keys => setExpanded(keys as string[]),
              expandRowByClick: true,
              rowExpandable: t => (t.lines ?? []).length > 0 || !!t.summary,
              expandedRowRender: t => (
                <pre style={{
                  margin: 0, maxHeight: 240, overflow: 'auto', fontSize: 11, fontFamily: MONO_FONT,
                  background: surfaces(isDark).sunken, border: '1px solid var(--rs-border)', borderRadius: RADIUS.sm, padding: '6px 8px',
                  whiteSpace: 'pre-wrap',
                }}>
                  {(t.lines ?? []).length ? (t.lines ?? []).join('\n') : t.summary}
                </pre>
              ),
            }}
          />
        </>
      )}
    </Modal>
  )
}

/** The activity list: every op this console session ran, newest first. */
function ActivityModal({ ops, onOpen, onClose }: {
  ops: MarketplaceOpRecord[]
  onOpen: (op: string) => void
  onClose: () => void
}) {
  const columns = [
    { title: 'Started', width: 110, render: (_: unknown, o: MarketplaceOpRecord) => <Text style={{ fontSize: 12 }}>{ago(o.started_at)}</Text> },
    { title: 'Operation', render: (_: unknown, o: MarketplaceOpRecord) => <span style={{ fontFamily: MONO_FONT, fontSize: 12 }}>{opLabel(o)}</span> },
    { title: 'Venvs', width: 70, render: (_: unknown, o: MarketplaceOpRecord) => <Text style={{ fontSize: 12 }}>{o.targets?.length ?? o.results.length}</Text> },
    { title: 'Status', width: 170, render: (_: unknown, o: MarketplaceOpRecord) => { const r = opOutcome(o); return <StatusTag tone={antTone(r.color)}>{r.text}</StatusTag> } },
  ]
  return (
    <Modal open title="Marketplace activity" width={760} onCancel={onClose} footer={<Button onClick={onClose}>Close</Button>}>
      {ops.length === 0 ? (
        <Text type="secondary">No installs, updates or removals yet in this session.</Text>
      ) : (
        <>
          <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 8 }}>Click an operation to see what happened on each venv.</Text>
          <Table size="small" rowKey="op" dataSource={ops} columns={columns} pagination={false}
            onRow={o => ({ onClick: () => onOpen(o.op), style: { cursor: 'pointer' } })} />
        </>
      )}
    </Modal>
  )
}

/** The op list, kept fresh from the progress/done events. */
function useMarketplaceOps() {
  const [ops, setOps] = useState<MarketplaceOpRecord[]>([])
  const reload = useCallback(async () => {
    try {
      const list = await bridge.marketplace_ops()
      if (Array.isArray(list)) setOps(list)
    } catch { /* an older backend without the list: no activity */ }
  }, [])
  useEffect(() => {
    reload()
    const onEvent = (e: Event) => {
      const d = (e as CustomEvent).detail || {}
      if (e.type === 'runspec:marketplace_done' || d.phase === 'start' || d.phase === 'done') reload()
    }
    window.addEventListener('runspec:marketplace_progress', onEvent)
    window.addEventListener('runspec:marketplace_done', onEvent)
    return () => {
      window.removeEventListener('runspec:marketplace_progress', onEvent)
      window.removeEventListener('runspec:marketplace_done', onEvent)
    }
  }, [reload])
  return { ops, reload }
}

// ── the view ───────────────────────────────────────────────────────────────

// Re-probe on window focus only when the last probe is older than this — the
// probe is an SSH fan-out, so we don't want to fire it on every focus flip.
const PROBE_STALE_S = 20

export function MarketplaceView({ hosts, onOpenSettings, activeProfile }: { hosts: Host[]; onOpenSettings?: () => void; activeProfile?: string }) {
  const isDark = useIsDark()
  const [catalog, setCatalog] = useState<MarketplaceCatalog | null>(null)
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [installed, setInstalled] = useState<MarketplaceInstalled | null>(null)
  const [probing, setProbing] = useState(false)
  const [search, setSearch] = useState('')
  const [repo, setRepo] = useState('')
  const [scope, setScope] = useState<ScopeFilter>('all')
  const [details, setDetails] = useState<MarketplaceEntry | null>(null)
  const [opFor, setOpFor] = useState<{ entry: MarketplaceEntry; action: 'install' | 'uninstall' } | null>(null)
  const [viewOp, setViewOp] = useState<string | null>(null)
  const [activityOpen, setActivityOpen] = useState(false)
  const { ops, reload: reloadOps } = useMarketplaceOps()
  const runningOps = useMemo(() => ops.filter(o => o.status === 'running'), [ops])
  const runningByPackage = useMemo(() => {
    const m = new Map<string, MarketplaceOpRecord[]>()
    for (const o of runningOps) {
      const name = o.package.split(/[=<>!~[;\s]/)[0].toLowerCase()
      m.set(name, [...(m.get(name) ?? []), o])
    }
    return m
  }, [runningOps])

  const loadCatalog = useCallback(async (refresh: boolean) => {
    setLoading(true)
    setLoadError(null)
    try {
      setCatalog(await bridge.marketplace_catalog(refresh))
    } catch (e) {
      setLoadError(e instanceof Error ? e.message : 'Could not read the package indexes')
    } finally {
      setLoading(false)
    }
  }, [])

  const probe = useCallback(async (refresh: boolean) => {
    setProbing(true)
    try {
      setInstalled(await bridge.marketplace_installed(refresh))
    } catch {
      /* the cards then show "not installed" until the next probe */
    } finally {
      setProbing(false)
    }
  }, [])

  useEffect(() => { loadCatalog(false); probe(false) }, [loadCatalog, probe])
  // A save in the Marketplace settings modal (enable, repos, hide…) re-reads the catalogue.
  useEffect(() => {
    const onCfg = () => { loadCatalog(false) }
    window.addEventListener('runspec:marketplace_config_changed', onCfg)
    return () => window.removeEventListener('runspec:marketplace_config_changed', onCfg)
  }, [loadCatalog])

  // A finished install/uninstall (from this or another mount) → re-probe; hosts
  // (re)connecting change the target set → re-probe too.
  const connectedKey = hosts.filter(h => h.connected).map(h => h.name).sort().join(',')
  useEffect(() => { if (installed) probe(true) }, [connectedKey]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    const onDone = () => probe(true)
    window.addEventListener('runspec:marketplace_done', onDone)
    return () => window.removeEventListener('runspec:marketplace_done', onDone)
  }, [probe])

  // Auto-refresh the installed probe when the tab/window regains focus, so the
  // per-venv chips can't silently show a stale result after the operator was
  // away (installs happen on the host between visits, or a profile was switched
  // elsewhere). Throttled to a stale probe only, and never while one's running —
  // read live state through refs so the listener isn't re-subscribed each probe.
  const installedRef = useRef(installed)
  const probingRef = useRef(probing)
  useEffect(() => { installedRef.current = installed }, [installed])
  useEffect(() => { probingRef.current = probing }, [probing])
  useEffect(() => {
    const maybeProbe = () => {
      if (document.visibilityState === 'hidden' || probingRef.current) return
      const at = installedRef.current?.probed_at
      if (at && Date.now() / 1000 - at < PROBE_STALE_S) return
      probe(true)
    }
    window.addEventListener('focus', maybeProbe)
    document.addEventListener('visibilitychange', maybeProbe)
    return () => {
      window.removeEventListener('focus', maybeProbe)
      document.removeEventListener('visibilitychange', maybeProbe)
    }
  }, [probe])

  // `host:` / `group:` in the search box narrow the venvs every card, count and
  // scope looks at; the rest of the search still matches package fields.
  const parsed = useMemo(() => parseSearch(search), [search])
  const groupOf = useMemo(() => {
    const m = new Map(hosts.map(h => [h.name, h.group || '']))
    return (host: string) => m.get(host)
  }, [hosts])
  const venvFilter = useMemo(() => targetFilter(parsed, groupOf), [parsed, groupOf])
  const allStatesFor = useCallback((e: MarketplaceEntry) => targetStates(e, installed), [installed])
  const statesFor = useCallback(
    (e: MarketplaceEntry) => (venvFilter ? allStatesFor(e).filter(s => venvFilter(s.target)) : allStatesFor(e)),
    [allStatesFor, venvFilter],
  )
  const entries = useMemo(() => catalog?.entries ?? [], [catalog])
  const filtered = useMemo(() => filterEntries(entries, { search: parsed.text, repo, scope }, statesFor), [entries, parsed.text, repo, scope, statesFor])
  const updates = useMemo(() => countUpdates(entries, statesFor), [entries, statesFor])
  const matchedVenvs = useMemo(
    () => (venvFilter && installed ? installed.targets.filter(venvFilter) : null),
    [venvFilter, installed],
  )
  // Keep the Marketplace tab badge in step with what the cards show (fleet-wide,
  // whatever the search).
  useEffect(() => {
    if (!installed || !catalog) return
    window.dispatchEvent(new CustomEvent('runspec:marketplace_updates', { detail: { count: countUpdates(entries, allStatesFor) } }))
  }, [installed, catalog, entries, allStatesFor])

  const refreshAll = () => { loadCatalog(true); probe(true) }
  const onOpStarted = useCallback((op: string) => {
    setOpFor(null)
    setViewOp(op)
    reloadOps()
  }, [reloadOps])

  if (catalog && !catalog.enabled) {
    return (
      <div style={{ padding: 24 }}>
        <Alert type="info" showIcon message="The marketplace is turned off" description="Turn it on in the marketplace settings ([marketplace] enabled = true in config.toml) to browse and install runnable packages."
          action={onOpenSettings && <Button size="small" icon={<SettingOutlined />} onClick={onOpenSettings}>Settings</Button>} />
      </div>
    )
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ marginBottom: 12, flexShrink: 0, display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
        <Tooltip title="Matches name, summary and keywords. host:<name> or group:<name> limits the install state, counts and Installed / Updates to those hosts' venvs (part of a name is enough).">
          <Input prefix={<SearchOutlined />} placeholder="Search packages, or host:<name>…" value={search} onChange={e => setSearch(e.target.value)} allowClear style={{ maxWidth: 320 }} />
        </Tooltip>
        <Select aria-label="Package index" value={repo} onChange={setRepo} style={{ minWidth: 160 }}
          options={[{ value: '', label: 'All repos' }, ...(catalog?.repos ?? []).map(r => ({ value: r.id, label: `${r.name} (${r.count})` }))]} />
        <Segmented value={scope} onChange={v => setScope(v as ScopeFilter)}
          options={[{ value: 'all', label: 'All' }, { value: 'installed', label: 'Installed' }, { value: 'updates', label: updates ? `Updates (${updates})` : 'Updates' }, { value: 'available', label: 'Not installed' }]} />
        <Tooltip title="Re-read the package indexes and re-probe every venv">
          <Button icon={<ReloadOutlined />} loading={loading || probing} onClick={refreshAll}>Refresh</Button>
        </Tooltip>
        <Tooltip title="Installs, updates and removals from this session. Several can run at once.">
          <Badge count={runningOps.length} size="small">
            <Button icon={<UnorderedListOutlined />} onClick={() => setActivityOpen(true)}>Activity</Button>
          </Badge>
        </Tooltip>
                {onOpenSettings && <Button type="text" icon={<SettingOutlined />} onClick={onOpenSettings}>Settings</Button>}
      </div>

      <div style={{ marginBottom: 12, flexShrink: 0, display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', fontSize: 12, color: textSecondary(isDark) }}>
        {(catalog?.repos ?? []).map(r => (
          <StatusTag key={r.id} tone={r.error ? (r.stale ? 'attention' : 'failed') : 'neutral'} tip={`${r.url}${r.error ? ` — ${r.error}` : ''}`}>
            {r.name} · {r.count} · {r.error ? (r.stale ? 'stale' : 'unreachable') : `read ${ago(r.fetched_at)}`}
          </StatusTag>
        ))}
        {installed && <span>venvs probed {ago(installed.probed_at)} · {installed.targets.filter(t => t.ok).length}/{installed.targets.length} reachable</span>}
        {matchedVenvs && (
          <Tooltip title={matchedVenvs.length ? matchedVenvs.map(t => `${t.host}/${t.venv}`).join(', ') : 'No probed venv is on a matching host. Hosts outside the active profile, or not connected, are not probed.'}>
            <Tag color={matchedVenvs.length ? 'blue' : 'red'} closable onClose={() => setSearch(parsed.text)} style={{ fontSize: 11, margin: 0 }}>
              {[...parsed.hosts.map(h => `host:${h}`), ...parsed.groups.map(g => `group:${g}`)].join(' ')} · {matchedVenvs.length} venv{matchedVenvs.length === 1 ? '' : 's'}
            </Tag>
          </Tooltip>
        )}
        {updates > 0 && scope !== 'updates' && (
          <StatusTag tone="attention" tip="Show only packages with a newer version than a venv has" onClick={() => setScope('updates')}>
            ↑ {updates} update{updates === 1 ? '' : 's'} available
          </StatusTag>
        )}
        {activeProfile && (
          <Tooltip title={`Install state covers only the venvs in the active host profile "${activeProfile}". A runnable installed on a host outside this profile shows as "not installed" until you switch to a profile that includes it (or pick "All hosts").`}>
            <Tag style={{ fontSize: 11, margin: 0 }}>profile: {activeProfile}</Tag>
          </Tooltip>
        )}
        {catalog?.errors?.length ? (
          <Tooltip title={<div style={{ whiteSpace: 'pre-wrap', fontFamily: MONO_FONT, fontSize: 11 }}>{catalog.errors.join('\n')}</div>}>
            <span><StatusTag tone="attention">{catalog.errors.length} package{catalog.errors.length === 1 ? '' : 's'} skipped</StatusTag></span>
          </Tooltip>
        ) : null}
      </div>

      {runningOps.length > 0 && (
        <div style={{ marginBottom: 12, flexShrink: 0, display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center', fontSize: 12 }}>
          <Text type="secondary" style={{ fontSize: 12 }}>Running:</Text>
          {runningOps.map(o => (
            <StatusTag key={o.op} tone="running" onClick={() => setViewOp(o.op)}>
              {opLabel(o)} · {opOutcome(o).text}
            </StatusTag>
          ))}
        </div>
      )}

      {loadError && <Alert type="error" showIcon message={loadError} style={{ marginBottom: 12 }} />}

      {loading && !catalog ? (
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--rs-text-muted)' }}>
          <Text type="secondary">Reading package indexes…</Text>
        </div>
      ) : filtered.length === 0 ? (
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--rs-text-muted)' }}>
          <div style={{ textAlign: 'center' }}>
            <AppstoreAddOutlined style={{ fontSize: 32, marginBottom: 12, display: 'block' }} />
            <Text type="secondary">{entries.length === 0 ? 'No runnable packages found in the configured indexes.' : 'Nothing matches the current filter.'}</Text>
            {entries.length > 0 && !venvFilter && parsed.text && hosts.some(h => parsed.text.toLowerCase().split(/\s+/).includes(h.name.toLowerCase())) && (
              <Text type="secondary" style={{ display: 'block', fontSize: 12, marginTop: 4 }}>To filter by a host, type <code>host:{parsed.text.split(/\s+/).find(w => hosts.some(h => h.name.toLowerCase() === w.toLowerCase()))}</code>.</Text>
            )}
          </div>
        </div>
      ) : (
        <div style={{ flex: 1, overflowY: 'auto' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: 10 }}>
            {filtered.map(e => (
              <PackageCard key={`${e.repo}/${e.name}`} entry={e} states={statesFor(e)} filtered={!!venvFilter}
                running={runningByPackage.get(e.name.toLowerCase())} onOpenOp={setViewOp}
                onInstall={() => setOpFor({ entry: e, action: 'install' })}
                onUninstall={() => setOpFor({ entry: e, action: 'uninstall' })}
                onDetails={() => setDetails(e)} />
            ))}
          </div>
        </div>
      )}

      <DetailsModal entry={details} onClose={() => setDetails(null)} />
      {opFor && (
        <OpModal entry={opFor.entry} action={opFor.action} states={allStatesFor(opFor.entry)} focus={venvFilter} groupOf={groupOf}
          onClose={() => setOpFor(null)} onStarted={onOpStarted} />
      )}
      {activityOpen && (
        <ActivityModal ops={ops} onClose={() => setActivityOpen(false)}
          onOpen={op => { setActivityOpen(false); setViewOp(op) }} />
      )}
      {viewOp && <OpDetailModal key={viewOp} opId={viewOp} onClose={() => setViewOp(null)} />}
    </div>
  )
}
